func TestBundleIsEmbeddedAndGenerated(t *testing.T) {
	t.Parallel()

	asset, ok := staticAssets[bundleName]
	if !ok {
		t.Fatalf("bundle %q is not embedded; run `just bundle`", bundleName)
	}

	if len(asset.content) == 0 {
		t.Fatal("embedded bundle is empty")
	}

	if !bytes.HasPrefix(asset.content, []byte("// Code generated by scripts/bundle-web.sh")) {
		t.Errorf("embedded bundle is missing the generated-file banner; first bytes: %q", firstLine(asset.content))
	}

	if !bytes.Contains(asset.content, []byte("data-island")) {
		t.Error("embedded bundle does not reference the data-island mount convention, so it cannot be the island entry point")
	}
}

func TestBundleURLCarriesTheContentHash(t *testing.T) {
	t.Parallel()

	url := BundleURL()

	prefix := StaticPrefix + bundleName + "?v="
	if !strings.HasPrefix(url, prefix) {
		t.Fatalf("BundleURL() = %q, want prefix %q", url, prefix)
	}

	version := strings.TrimPrefix(url, prefix)
	if version != staticAssets[bundleName].version {
		t.Errorf("BundleURL() version = %q, want %q", version, staticAssets[bundleName].version)
	}

	if len(version) != 16 {
		t.Errorf("version %q is %d characters, want 16", version, len(version))
	}
}

func TestStaticHandlerServesTheBundle(t *testing.T) {
	t.Parallel()

	recorder := httptest.NewRecorder()
	request := httptest.NewRequest(http.MethodGet, BundleURL(), nil)
	StaticHandler().ServeHTTP(recorder, request)

	if recorder.Code != http.StatusOK {
		t.Fatalf("status = %d, want %d", recorder.Code, http.StatusOK)
	}

	if got, want := recorder.Header().Get("Content-Type"), "text/javascript; charset=utf-8"; got != want {
		t.Errorf("Content-Type = %q, want %q", got, want)
	}

	if got, want := recorder.Header().Get("X-Content-Type-Options"), "nosniff"; got != want {
		t.Errorf("X-Content-Type-Options = %q, want %q", got, want)
	}
	// A URL that names the version it receives can never go stale, so it is
	// the only case allowed to opt out of revalidation.
	if got, want := recorder.Header().Get("Cache-Control"), "public, max-age=31536000, immutable"; got != want {
		t.Errorf("Cache-Control = %q, want %q", got, want)
	}

	if !bytes.Equal(recorder.Body.Bytes(), staticAssets[bundleName].content) {
		t.Error("served body does not match the embedded bundle")
	}
}

func TestStaticHandlerRevalidatesUnversionedAndStaleURLs(t *testing.T) {
	t.Parallel()

	for name, url := range map[string]string{
		"no version":    StaticPrefix + bundleName,
		"stale version": StaticPrefix + bundleName + "?v=0000000000000000",
	} {
		t.Run(name, func(t *testing.T) {
			t.Parallel()

			recorder := httptest.NewRecorder()
			StaticHandler().ServeHTTP(recorder, httptest.NewRequest(http.MethodGet, url, nil))

			if recorder.Code != http.StatusOK {
				t.Fatalf("status = %d, want %d", recorder.Code, http.StatusOK)
			}

			if got, want := recorder.Header().Get("Cache-Control"), "no-cache"; got != want {
				t.Errorf("Cache-Control = %q, want %q", got, want)
			}
		})
	}
}

func TestStaticHandlerHonorsIfNoneMatch(t *testing.T) {
	t.Parallel()

	request := httptest.NewRequest(http.MethodGet, BundleURL(), nil)
	request.Header.Set("If-None-Match", staticAssets[bundleName].etag)

	recorder := httptest.NewRecorder()
	StaticHandler().ServeHTTP(recorder, request)

	if recorder.Code != http.StatusNotModified {
		t.Fatalf("status = %d, want %d", recorder.Code, http.StatusNotModified)
	}

	if recorder.Body.Len() != 0 {
		t.Errorf("304 response carried %d bytes of body", recorder.Body.Len())
	}
}

func TestStaticHandlerRejectsAnythingNotEmbedded(t *testing.T) {
	t.Parallel()

	cases := map[string]struct {
		method string
		url    string
		want   int
	}{
		"unknown asset":     {http.MethodGet, StaticPrefix + "nope.js", http.StatusNotFound},
		"directory listing": {http.MethodGet, StaticPrefix, http.StatusNotFound},
		"nested path":       {http.MethodGet, StaticPrefix + "sub/dashboard.js", http.StatusNotFound},
		"traversal":         {http.MethodGet, StaticPrefix + "../go.mod", http.StatusNotFound},
		"write attempt":     {http.MethodPost, StaticPrefix + bundleName, http.StatusMethodNotAllowed},
	}
	for name, testCase := range cases {
		t.Run(name, func(t *testing.T) {
			t.Parallel()

			recorder := httptest.NewRecorder()
			StaticHandler().ServeHTTP(recorder, httptest.NewRequest(testCase.method, testCase.url, nil))

			if recorder.Code != testCase.want {
				t.Errorf("status = %d, want %d", recorder.Code, testCase.want)
			}
		})
	}
}

func TestIslandBundleLoadsTheVersionedBundle(t *testing.T) {
	t.Parallel()

	var output bytes.Buffer

	err := IslandBundle().Render(context.Background(), &output)
	if err != nil {
		t.Fatalf("render island bundle: %v", err)
	}

	body := output.String()
	if !strings.Contains(body, `type="module"`) {
		t.Error("IslandBundle does not load the bundle as a module script")
	}
	// The versioned URL must reach the markup: a page that links the
	// unversioned path would keep serving a stale bundle from cache after a
	// rebuild.
	if !strings.Contains(body, BundleURL()) {
		t.Errorf("IslandBundle does not reference %q", BundleURL())
	}
}

// The bundle used to be opt-in per page, so that a page with no island would
// not fetch and parse it. Task 18.3 ended that distinction rather than relaxing
// it: the theme switch in the navigation is an island now, the layout renders it
// on every page, and a page whose chrome does not mount has a dead control in
// it. So the layout loads the bundle itself, and Task 18.7 deleted the five
// leftover per-page call sites that Task 18.3 had left in place. There is one
// link, and it is in the shell; see TestOnlyTheLayoutLinksTheIslandBundle.
func TestLayoutLoadsTheIslandBundle(t *testing.T) {
	t.Parallel()

	var output bytes.Buffer

	err := Layout("Bundle test").Render(context.Background(), &output)
	if err != nil {
		t.Fatalf("render layout: %v", err)
	}

	body := output.String()
	if !strings.Contains(body, BundleURL()) {
		t.Errorf("layout does not link %s, so the theme switch would never mount", bundleName)
	}

	if !strings.Contains(body, `data-island="theme-switch"`) {
		t.Error("layout loads the bundle but renders no mount point for the theme switch")
	}
}

// The bundle embeds compiled copies of its npm dependencies and is
// redistributed inside release binaries, so their licence banners have to
// survive minification. See THIRD-PARTY-NOTICES.md.
func TestBundleKeepsDependencyLicenseNotices(t *testing.T) {
	t.Parallel()

	bundle, err := staticFS.ReadFile("static/" + bundleName)
	if err != nil {
		t.Fatalf("read bundle: %v", err)
	}

	for _, notice := range []string{"@license React", "Copyright (c) Meta Platforms, Inc. and affiliates."} {
		if !bytes.Contains(bundle, []byte(notice)) {
			t.Errorf("bundle is missing the notice %q; is --legal-comments still set?", notice)
		}
	}
}

func firstLine(content []byte) []byte {
	if before, _, ok := bytes.Cut(content, []byte{'\n'}); ok {
		return before
	}

	return content
}

// The map is what makes a minified island stack trace readable. It is
// committed and embedded exactly like the bundle, so a build without node
// still ships it.
func TestBundleSourceMapIsEmbeddedAndComplete(t *testing.T) {
	t.Parallel()

	asset, ok := staticAssets[bundleMapName]
	if !ok {
		t.Fatalf("source map %q is not embedded; run `just bundle`", bundleMapName)
	}

	var sourceMap struct {
		Version        int      `json:"version"`
		Sources        []string `json:"sources"`
		SourcesContent []string `json:"sourcesContent"`
		Mappings       string   `json:"mappings"`
	}

	err := json.Unmarshal(asset.content, &sourceMap)
	if err != nil {
		t.Fatalf("embedded source map is not valid JSON: %v", err)
	}

	if sourceMap.Version != 3 {
		t.Errorf("source map version = %d, want 3", sourceMap.Version)
	}

	if sourceMap.Mappings == "" {
		t.Error("source map carries no mappings, so it maps nothing")
	}
	// Without sourcesContent devtools would go looking for web/src on the
	// server, and the flat static namespace serves no such tree.
	if len(sourceMap.SourcesContent) != len(sourceMap.Sources) {
		t.Errorf("source map has %d sources but %d sourcesContent entries; is --sources-content still on?",
			len(sourceMap.Sources), len(sourceMap.SourcesContent))
	}
	var hasEntryPoint bool

	for _, source := range sourceMap.Sources {
		if strings.HasSuffix(source, "web/src/dashboard.tsx") {
			hasEntryPoint = true
		}
		// A machine-specific absolute path would make the drift gate fail on
		// every developer's checkout.
		if path.IsAbs(source) {
			t.Errorf("source map names the absolute path %q", source)
		}
	}

	if !hasEntryPoint {
		t.Error("source map does not cover web/src/dashboard.tsx")
	}
}

// The comment is the only thing that tells a browser the map exists, and it is
// resolved against the bundle's own URL, so it must name a sibling the flat
// static handler will actually serve.
func TestBundleLinksItsSourceMap(t *testing.T) {
	t.Parallel()

	bundle := staticAssets[bundleName].content

	want := "//# sourceMappingURL=" + bundleMapName
	if !bytes.Contains(bundle, []byte(want)) {
		t.Fatalf("bundle does not end with %q; is --sourcemap still set?", want)
	}

	if bytes.Contains(bundle, []byte("sourceMappingURL=data:")) {
		t.Error("bundle inlines its source map; the linked map is the committed form")
	}

	base, err := url.Parse(BundleURL())
	if err != nil {
		t.Fatalf("parse bundle URL: %v", err)
	}

	resolved, err := base.Parse(bundleMapName)
	if err != nil {
		t.Fatalf("resolve source map URL: %v", err)
	}

	if got, want := resolved.Path, StaticPrefix+bundleMapName; got != want {
		t.Fatalf("browser would fetch %q, want %q", got, want)
	}

	recorder := httptest.NewRecorder()
	StaticHandler().ServeHTTP(recorder, httptest.NewRequest(http.MethodGet, resolved.String(), nil))

	if recorder.Code != http.StatusOK {
		t.Fatalf("status = %d, want %d", recorder.Code, http.StatusOK)
	}

	if got, want := recorder.Header().Get("Content-Type"), "application/json; charset=utf-8"; got != want {
		t.Errorf("Content-Type = %q, want %q", got, want)
	}

	if got, want := recorder.Header().Get("X-Content-Type-Options"), "nosniff"; got != want {
		t.Errorf("X-Content-Type-Options = %q, want %q", got, want)
	}
	// esbuild's comment carries no ?v=, so the map is fetched unversioned and
	// has to revalidate rather than be pinned forever.
	if got, want := recorder.Header().Get("Cache-Control"), "no-cache"; got != want {
		t.Errorf("Cache-Control = %q, want %q", got, want)
	}

	if !bytes.Equal(recorder.Body.Bytes(), staticAssets[bundleMapName].content) {
		t.Error("served body does not match the embedded source map")
	}
}

// The map is a devtools-only download; the page itself must never pull two
// megabytes of sources on load.
func TestIslandBundleDoesNotLinkTheSourceMap(t *testing.T) {
	t.Parallel()

	var output bytes.Buffer

	err := IslandBundle().Render(context.Background(), &output)
	if err != nil {
		t.Fatalf("render island bundle: %v", err)
	}

	if strings.Contains(output.String(), bundleMapName) {
		t.Errorf("IslandBundle references %s; the browser fetches it from the bundle comment only", bundleMapName)
	}
}
